//! Rust translation of `reference/version.py` (python-semver), std-only.
//!
//! Only the pure-Python parsing/comparison/bump behaviour needed by the
//! fixed contract (`parse`, `to_string`, `compare`, `bump_major`,
//! `bump_minor`, `bump_patch`) is translated. The struct's field names and
//! types are frozen by the harness contract.

use std::cmp::Ordering;

/// A parsed semantic version.
///
/// `prerelease` and `build` hold the text *after* the `-` and `+`
/// respectively, with the separator stripped, or `None` when absent.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Version {
    pub major: u64,
    pub minor: u64,
    pub patch: u64,
    pub prerelease: Option<String>,
    pub build: Option<String>,
}

/// Returns true if `ident` is a valid dot-separated component of a
/// prerelease string, i.e. it matches
/// `0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*` (ASCII only).
fn is_valid_prerelease_identifier(ident: &str) -> bool {
    if ident.is_empty() {
        return false;
    }
    let all_digits = ident.bytes().all(|b| b.is_ascii_digit());
    if all_digits {
        // matches `0` or `[1-9]\d*`: no leading zero unless the value is
        // exactly "0".
        return ident.as_bytes()[0] != b'0' || ident.len() == 1;
    }
    // Otherwise it must match `\d*[a-zA-Z-][0-9a-zA-Z-]*`, i.e. consist
    // entirely of ASCII alphanumerics and hyphens (we already know it is
    // not all-digits, so it necessarily contains a letter or hyphen).
    ident
        .bytes()
        .all(|b| b.is_ascii_alphanumeric() || b == b'-')
}

/// Returns true if `ident` is a valid dot-separated build identifier,
/// i.e. it matches `[0-9a-zA-Z-]+` (ASCII only).
fn is_valid_build_identifier(ident: &str) -> bool {
    !ident.is_empty()
        && ident
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || b == b'-')
}

/// Parse a version string. Return `Err` with a short reason for anything
/// that is not a valid semver 2.0.0 string.
pub fn parse(s: &str) -> Result<Version, String> {
    let fail = || format!("{} is not valid SemVer string", s);

    if !s.is_ascii() {
        return Err(fail());
    }
    let bytes = s.as_bytes();
    let len = bytes.len();
    let mut i: usize = 0;

    // Scan a numeric component (major/minor/patch): digits only, no
    // leading zero unless the value is exactly "0".
    let scan_number = |s: &str, bytes: &[u8], start: usize| -> Result<(usize, usize), String> {
        let mut j = start;
        while j < len && bytes[j].is_ascii_digit() {
            j += 1;
        }
        if j == start {
            return Err(fail_static(s));
        }
        let comp = &s[start..j];
        if comp.len() > 1 && comp.as_bytes()[0] == b'0' {
            return Err(fail_static(s));
        }
        Ok((start, j))
    };
    fn fail_static(s: &str) -> String {
        format!("{} is not valid SemVer string", s)
    }

    let (ms, me) = scan_number(s, bytes, i)?;
    let major_str = &s[ms..me];
    i = me;
    if i >= len || bytes[i] != b'.' {
        return Err(fail());
    }
    i += 1;

    let (ns, ne) = scan_number(s, bytes, i)?;
    let minor_str = &s[ns..ne];
    i = ne;
    if i >= len || bytes[i] != b'.' {
        return Err(fail());
    }
    i += 1;

    let (ps, pe) = scan_number(s, bytes, i)?;
    let patch_str = &s[ps..pe];
    i = pe;

    let major: u64 = major_str.parse().map_err(|_| fail())?;
    let minor: u64 = minor_str.parse().map_err(|_| fail())?;
    let patch: u64 = patch_str.parse().map_err(|_| fail())?;

    let rest = &s[i..];
    let rest_bytes = rest.as_bytes();
    let mut pos: usize = 0;
    let mut prerelease: Option<String> = None;
    let mut build: Option<String> = None;

    if pos < rest_bytes.len() && rest_bytes[pos] == b'-' {
        let start_pre = pos + 1;
        let pre_end = match rest[start_pre..].find('+') {
            Some(p) => start_pre + p,
            None => rest.len(),
        };
        let pre_str = &rest[start_pre..pre_end];
        if pre_str.is_empty() {
            return Err(fail());
        }
        for ident in pre_str.split('.') {
            if !is_valid_prerelease_identifier(ident) {
                return Err(fail());
            }
        }
        prerelease = Some(pre_str.to_string());
        pos = pre_end;
    }

    if pos < rest_bytes.len() && rest_bytes[pos] == b'+' {
        let start_build = pos + 1;
        let build_str = &rest[start_build..];
        if build_str.is_empty() {
            return Err(fail());
        }
        for ident in build_str.split('.') {
            if !is_valid_build_identifier(ident) {
                return Err(fail());
            }
        }
        build = Some(build_str.to_string());
        pos = rest.len();
    }

    if pos != rest.len() {
        return Err(fail());
    }

    Ok(Version {
        major,
        minor,
        patch,
        prerelease,
        build,
    })
}

/// Render a `Version` back to its canonical string form.
pub fn to_string(v: &Version) -> String {
    let mut s = format!("{}.{}.{}", v.major, v.minor, v.patch);
    if let Some(pre) = &v.prerelease {
        if !pre.is_empty() {
            s.push('-');
            s.push_str(pre);
        }
    }
    if let Some(b) = &v.build {
        if !b.is_empty() {
            s.push('+');
            s.push_str(b);
        }
    }
    s
}

/// True if `ident` (a dot-separated component) consists only of ASCII
/// digits (mirrors Python's `str.isdigit()` restricted to our validated
/// ASCII-only inputs).
fn is_numeric(ident: &str) -> bool {
    !ident.is_empty() && ident.bytes().all(|b| b.is_ascii_digit())
}

/// Compare two numeric identifier strings by value, without overflowing:
/// strip any leading zeros (Python converts to `int`, which ignores
/// them), then compare by length, then lexically.
fn cmp_numeric_str(a: &str, b: &str) -> Ordering {
    let a_trimmed = a.trim_start_matches('0');
    let b_trimmed = b.trim_start_matches('0');
    let a_use = if a_trimmed.is_empty() { "0" } else { a_trimmed };
    let b_use = if b_trimmed.is_empty() { "0" } else { b_trimmed };
    match a_use.len().cmp(&b_use.len()) {
        Ordering::Equal => a_use.cmp(b_use),
        other => other,
    }
}

fn cmp_prerelease_tag(a: &str, b: &str) -> Ordering {
    match (is_numeric(a), is_numeric(b)) {
        (true, true) => cmp_numeric_str(a, b),
        (true, false) => Ordering::Less,
        (false, true) => Ordering::Greater,
        (false, false) => a.cmp(b),
    }
}

/// Mirrors `Version._nat_cmp`.
fn nat_cmp(a: Option<&str>, b: Option<&str>) -> Ordering {
    let a_str = a.unwrap_or("");
    let b_str = b.unwrap_or("");
    let a_parts: Vec<&str> = a_str.split('.').collect();
    let b_parts: Vec<&str> = b_str.split('.').collect();

    for (pa, pb) in a_parts.iter().zip(b_parts.iter()) {
        let ord = cmp_prerelease_tag(pa, pb);
        if ord != Ordering::Equal {
            return ord;
        }
    }
    a_parts.len().cmp(&b_parts.len())
}

/// Semver precedence, mirroring `Version.compare`.
pub fn compare(a: &Version, b: &Version) -> Ordering {
    let main_cmp = (a.major, a.minor, a.patch).cmp(&(b.major, b.minor, b.patch));
    if main_cmp != Ordering::Equal {
        return main_cmp;
    }

    let rc1 = a.prerelease.as_deref();
    let rc2 = b.prerelease.as_deref();
    let rccmp = nat_cmp(rc1, rc2);

    if rccmp == Ordering::Equal {
        return Ordering::Equal;
    }

    let rc1_truthy = matches!(rc1, Some(s) if !s.is_empty());
    let rc2_truthy = matches!(rc2, Some(s) if !s.is_empty());

    if !rc1_truthy {
        Ordering::Greater
    } else if !rc2_truthy {
        Ordering::Less
    } else {
        rccmp
    }
}

/// Increment major; reset minor and patch; drop prerelease and build.
pub fn bump_major(v: &Version) -> Version {
    Version {
        major: v.major.saturating_add(1),
        minor: 0,
        patch: 0,
        prerelease: None,
        build: None,
    }
}

/// Increment minor; reset patch; drop prerelease and build.
pub fn bump_minor(v: &Version) -> Version {
    Version {
        major: v.major,
        minor: v.minor.saturating_add(1),
        patch: 0,
        prerelease: None,
        build: None,
    }
}

/// Increment patch; drop prerelease and build.
pub fn bump_patch(v: &Version) -> Version {
    Version {
        major: v.major,
        minor: v.minor,
        patch: v.patch.saturating_add(1),
        prerelease: None,
        build: None,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn v(major: u64, minor: u64, patch: u64, pre: Option<&str>, build: Option<&str>) -> Version {
        Version {
            major,
            minor,
            patch,
            prerelease: pre.map(|s| s.to_string()),
            build: build.map(|s| s.to_string()),
        }
    }

    #[test]
    fn test_should_parse_version() -> Result<(), String> {
        let r = parse("1.2.3-alpha.1.2+build.11.e0f985a")?;
        assert_eq!(
            r,
            v(1, 2, 3, Some("alpha.1.2"), Some("build.11.e0f985a"))
        );

        let r = parse("1.2.3-alpha-1+build.11.e0f985a")?;
        assert_eq!(r, v(1, 2, 3, Some("alpha-1"), Some("build.11.e0f985a")));

        let r = parse("0.1.0-0f")?;
        assert_eq!(r, v(0, 1, 0, Some("0f"), None));

        let r = parse("0.0.0-0foo.1")?;
        assert_eq!(r, v(0, 0, 0, Some("0foo.1"), None));

        let r = parse("0.0.0-0foo.1+build.1")?;
        assert_eq!(r, v(0, 0, 0, Some("0foo.1"), Some("build.1")));
        Ok(())
    }

    #[test]
    fn test_should_parse_zero_prerelease() -> Result<(), String> {
        let r = parse("1.2.3-rc.0+build.0")?;
        assert_eq!(r, v(1, 2, 3, Some("rc.0"), Some("build.0")));

        let r = parse("1.2.3-rc.0.0+build.0")?;
        assert_eq!(r, v(1, 2, 3, Some("rc.0.0"), Some("build.0")));
        Ok(())
    }

    #[test]
    fn test_should_raise_value_error_for_zero_prefixed_versions() {
        assert!(parse("01.2.3").is_err());
        assert!(parse("1.02.3").is_err());
        assert!(parse("1.2.03").is_err());
    }

    #[test]
    fn test_should_raise_value_error_for_invalid_value() {
        assert!(parse("foo").is_err());
        assert!(parse("1.0").is_err());
        assert!(parse("1.x").is_err());
    }

    #[test]
    fn test_parse_method_roundtrip() -> Result<(), String> {
        let s_version = "1.2.3-alpha.1.2+build.11.e0f985a";
        let ver = parse(s_version)?;
        assert_eq!(to_string(&ver), s_version);
        Ok(())
    }

    #[test]
    fn test_should_get_less() {
        let pairs = [
            ("1.0.0", "2.0.0"),
            ("1.0.0-alpha", "1.0.0-alpha.1"),
            ("1.0.0-alpha.1", "1.0.0-alpha.beta"),
            ("1.0.0-alpha.beta", "1.0.0-beta"),
            ("1.0.0-beta", "1.0.0-beta.2"),
            ("1.0.0-beta.2", "1.0.0-beta.11"),
            ("1.0.0-beta.11", "1.0.0-rc.1"),
            ("1.0.0-rc.1", "1.0.0"),
        ];
        for (l, r) in pairs {
            let (lv, rv) = match (parse(l), parse(r)) {
                (Ok(a), Ok(b)) => (a, b),
                _ => panic!("unreachable in test setup"),
            };
            assert_eq!(compare(&lv, &rv), Ordering::Less, "{} vs {}", l, r);
        }
    }

    #[test]
    fn test_should_get_greater() -> Result<(), String> {
        let pairs = [
            ("2.0.0", "1.0.0"),
            ("1.0.0-alpha.1", "1.0.0-alpha"),
            ("1.0.0-alpha.beta", "1.0.0-alpha.1"),
            ("1.0.0-beta", "1.0.0-alpha.beta"),
            ("1.0.0-beta.2", "1.0.0-beta"),
            ("1.0.0-beta.11", "1.0.0-beta.2"),
            ("1.0.0-rc.1", "1.0.0-beta.11"),
            ("1.0.0", "1.0.0-rc.1"),
        ];
        for (l, r) in pairs {
            let lv = parse(l)?;
            let rv = parse(r)?;
            assert_eq!(compare(&lv, &rv), Ordering::Greater, "{} vs {}", l, r);
        }
        Ok(())
    }

    #[test]
    fn test_should_follow_specification_comparison() -> Result<(), String> {
        let chain = [
            "1.0.0-alpha",
            "1.0.0-alpha.1",
            "1.0.0-beta.2",
            "1.0.0-beta.11",
            "1.0.0-rc.1",
            "1.0.0",
            "1.3.7+build",
        ];
        for w in chain.windows(2) {
            let lo = parse(w[0])?;
            let hi = parse(w[1])?;
            assert_eq!(compare(&lo, &hi), Ordering::Less);
            assert_eq!(compare(&hi, &lo), Ordering::Greater);
        }
        Ok(())
    }

    #[test]
    fn test_should_say_equal_versions_are_equal() -> Result<(), String> {
        let pairs = [
            ("2.0.0", "2.0.0"),
            ("1.1.9-rc.1", "1.1.9-rc.1"),
            ("1.1.9+build.1", "1.1.9+build.1"),
            ("1.1.9-rc.1+build.1", "1.1.9-rc.1+build.1"),
        ];
        for (l, r) in pairs {
            let lv = parse(l)?;
            let rv = parse(r)?;
            assert_eq!(compare(&lv, &rv), Ordering::Equal);
        }
        Ok(())
    }

    #[test]
    fn test_should_compare_versions_with_build_and_release() -> Result<(), String> {
        let a = parse("1.1.9-rc.1")?;
        let b = parse("1.1.9-rc.1+build.1")?;
        assert_eq!(compare(&a, &b), Ordering::Equal);

        let a = parse("1.1.9-rc.1")?;
        let b = parse("1.1.9+build.1")?;
        assert_eq!(compare(&a, &b), Ordering::Less);
        Ok(())
    }

    #[test]
    fn test_should_ignore_builds_on_compare() -> Result<(), String> {
        let cases = [
            ("1.0.0+build.1", "1.0.0", Ordering::Equal),
            ("1.0.0-alpha.1+build.1", "1.0.0-alpha.1", Ordering::Equal),
            ("1.0.0+build.1", "1.0.0-alpha.1", Ordering::Greater),
            (
                "1.0.0+build.1",
                "1.0.0-alpha.1+build.1",
                Ordering::Greater,
            ),
        ];
        for (l, r, expected) in cases {
            let lv = parse(l)?;
            let rv = parse(r)?;
            assert_eq!(compare(&lv, &rv), expected, "{} vs {}", l, r);
        }
        Ok(())
    }

    #[test]
    fn test_should_get_more_rc1() -> Result<(), String> {
        let a = parse("1.0.0-rc1")?;
        let b = parse("1.0.0-rc0")?;
        assert_eq!(compare(&a, &b), Ordering::Greater);
        Ok(())
    }

    #[test]
    fn test_should_compare_prerelease_with_numbers_and_letters() {
        let v1 = v(1, 9, 1, Some("1unms"), None);
        let v2 = v(1, 9, 1, None, Some("1asd"));
        assert_eq!(compare(&v1, &v2), Ordering::Less);
    }

    #[test]
    fn test_should_compare_prerelease_and_build_with_numbers() {
        let a = v(1, 9, 1, Some("1"), Some("1"));
        let b = v(1, 9, 1, Some("2"), Some("1"));
        assert_eq!(compare(&a, &b), Ordering::Less);

        let a = v(0, 0, 2, None, None);
        let b = v(0, 0, 10, None, None);
        assert_eq!(compare(&a, &b), Ordering::Less);
    }

    #[test]
    fn test_should_bump_major() -> Result<(), String> {
        let start = parse("3.4.5")?;
        assert_eq!(to_string(&bump_major(&start)), "4.0.0");
        Ok(())
    }

    #[test]
    fn test_should_bump_minor() -> Result<(), String> {
        let start = parse("3.4.5")?;
        assert_eq!(to_string(&bump_minor(&start)), "3.5.0");
        Ok(())
    }

    #[test]
    fn test_should_bump_patch() -> Result<(), String> {
        let start = parse("3.4.5")?;
        assert_eq!(to_string(&bump_patch(&start)), "3.4.6");
        Ok(())
    }

    #[test]
    fn test_should_ignore_extensions_for_bump() -> Result<(), String> {
        let start = parse("3.4.5-rc1+build4")?;
        assert_eq!(to_string(&bump_patch(&start)), "3.4.6");
        Ok(())
    }

    #[test]
    fn test_should_versioninfo_bump_major_and_minor() -> Result<(), String> {
        let start = parse("3.4.5")?;
        let bumped = bump_minor(&bump_major(&start));
        let expected = parse("4.1.0")?;
        assert_eq!(bumped, expected);
        Ok(())
    }

    #[test]
    fn test_should_versioninfo_bump_minor_and_patch() -> Result<(), String> {
        let start = parse("3.4.5")?;
        let bumped = bump_patch(&bump_minor(&start));
        let expected = parse("3.5.1")?;
        assert_eq!(bumped, expected);
        assert_eq!(compare(&start, &expected), Ordering::Less);
        Ok(())
    }

    #[test]
    fn test_should_raise_error_on_invalid_characters() {
        assert!(parse("1.2.3-üñïçødé").is_err());
        assert!(parse("").is_err());
        assert!(parse("1.2.3-").is_err());
        assert!(parse("1.2.3+").is_err());
        assert!(parse(" 1.2.3").is_err());
        assert!(parse("1.2.3 ").is_err());
    }

    #[test]
    fn test_roundtrip_all_parts() -> Result<(), String> {
        let s = "10.20.30-pre-release.1+build-meta.2";
        let ver = parse(s)?;
        assert_eq!(to_string(&ver), s);
        Ok(())
    }
}

